header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function relp($p,$r){$x=realpath($p);return $x?ltrim(str_replace('\\','/',substr($x,strlen($r))),'/'):'';}
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan_site($root){global $TEXT;$files=[];$dirs=[];try{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$p=relp($f->getPathname(),$root);if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;elseif($f->isFile())$files[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];}}catch(Throwable $e){}sort($dirs);ksort($files);$refs=[];$rx=['/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i','/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];foreach($files as $p=>$m){if(!$m['text']||$m['size']>700000)continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;$vals=[];foreach($rx as $re){preg_match_all($re,$s,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$vals[]=$v;}}foreach(array_unique($vals) as $v){$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}return ['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan_site($ROOT);if(isset($_GET['pulse'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'files'=>count($D['files']),'links'=>count($D['refs'])]);exit;}if(isset($_GET['data'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode($D,JSON_UNESCAPED_SLASHES);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#070b10;color:#dce7ee;font-family:Inter,system-ui,Segoe UI,Arial}body{background:radial-gradient(circle at 52% 48%,#12202a 0,#070b10 48%,#040609 100%)}#graph{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:4;top:18px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.title{font-size:21px;font-weight:800}.title b{color:#55dfcb}.sub{margin-top:5px;color:#5f747e;font:8px ui-monospace;letter-spacing:1.2px}.hud{display:flex;gap:6px}.chip,.search,.btn,.inspect{background:#0a1218e8;border:1px solid #7896a41f;border-radius:9px;backdrop-filter:blur(12px)}.chip{padding:7px 10px}.chip small{display:block;color:#526b76;font:7px ui-monospace}.chip strong{font:11px ui-monospace}.live{color:#59e4b5}.search{position:fixed;z-index:5;top:78px;left:22px;width:245px;padding:10px;color:#fff;outline:0;font:9px ui-monospace}.inspect{position:fixed;z-index:8;right:22px;top:78px;width:310px;padding:15px;display:none}.inspect.show{display:block}.close{float:right;background:none;border:0;color:#6e858e;font-size:18px}.tag{color:#56737d;font:7px ui-monospace;letter-spacing:1.4px}.inspect h2{font-size:15px;margin:7px 0}.path{color:#63d8ce;font:8px ui-monospace;word-break:break-all}.links{margin-top:11px;color:#78919a;font:8px ui-monospace;line-height:1.75;max-height:260px;overflow:auto}.links b{color:#b9cbd2}.controls{position:fixed;z-index:5;left:22px;bottom:18px;display:flex;gap:6px}.btn{padding:8px 11px;color:#9bb1b9;font:800 8px ui-monospace;cursor:pointer}.btn:hover{border-color:#55dfcb66;color:#eaffff}.status{position:fixed;z-index:5;right:22px;bottom:21px;color:#607983;font:8px ui-monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#59e4b5;box-shadow:0 0 12px #59e4b5;margin-right:6px;animation:beat 1.4s ease-in-out infinite}@keyframes beat{50%{opacity:.3;transform:scale(.65)}}.load{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#05090df7}.loadbox{text-align:center}.loadbox .ring{width:34px;height:34px;border:1px solid #29414b;border-top-color:#55dfcb;border-radius:50%;animation:spin .7s linear infinite;margin:auto}.loadbox b{display:block;margin-top:11px;font-size:10px}.loadbox span{display:block;margin-top:4px;color:#58717b;font:8px ui-monospace}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:700px){.top{left:11px;right:11px}.title{font-size:17px}.sub{display:none}.hud .chip:nth-child(n+3){display:none}.search{left:11px;top:66px;width:190px}.inspect{left:11px;right:11px;top:66px;width:auto}.controls{left:11px;bottom:11px}.status{right:11px;bottom:50px}}
</style></head><body><div class="load" id="load"><div class="loadbox"><div class="ring"></div><b>Mapping relationships…</b><span>Reading live server filesystem</span></div></div><div class="top"><div><div class="title"><b>●</b> SmartToolz <span>Relationship Manager</span></div><div class="sub">LIVE DEPENDENCY GRAPH • SERVER FILES • CLICK TO INSPECT</div></div><div class="hud"><div class="chip"><small>FILES</small><strong id="files">0</strong></div><div class="chip"><small>RELATIONS</small><strong id="rels">0</strong></div><div class="chip"><small>STATUS</small><strong class="live" id="state">LIVE</strong></div></div></div><input id="search" class="search" placeholder="Search files…"><canvas id="graph"></canvas><div id="inspect" class="inspect"><button class="close" id="close">×</button><div class="tag">NODE RELATIONSHIPS</div><h2 id="name"></h2><div id="path" class="path"></div><div id="links" class="links"></div></div><div class="controls"><button class="btn" id="center">CENTER</button><button class="btn" id="pause">PAUSE</button><button class="btn" id="refresh">RESCAN</button></div><div class="status"><span class="led"></span>SERVER <b id="hb">CONNECTING</b></div><script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>,c=document.getElementById('graph'),x=c.getContext('2d');let W,H,dpr=1,nodes=[],edges=[],adj=new Map(),selected=null,hover=null,zoom=.8,panX=0,panY=0,drag=false,lx=0,ly=0,paused=false;
const hash=s=>{let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return(h>>>0)/4294967296};function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;c.width=W*dpr;c.height=H*dpr;x.setTransform(dpr,0,0,dpr,0,0);layout()}addEventListener('resize',resize);
function edge(a,b,type){if(!a||!b||a===b)return;const k=a.id+'>'+b.id;if(edges.some(e=>e.k===k))return;edges.push({a,b,type,k,p:hash(k)});if(!adj.has(a.id))adj.set(a.id,[]);if(!adj.has(b.id))adj.set(b.id,[]);adj.get(a.id).push(b);adj.get(b.id).push(a)}
function build(){const map=new Map;nodes=[];for(const d of D.dirs)nodes.push({id:'d:'+d,path:d,name:d.split('/').pop()+'/',folder:true,x:0,y:0});for(const f of D.files)nodes.push({id:'f:'+f,path:f,name:f.split('/').pop(),folder:false,x:0,y:0});nodes.forEach(n=>map.set(n.id,n));for(const n of nodes){const q=n.path.split('/');if(q.length>1)edge(map.get('d:'+q.slice(0,-1).join('/')),n,'tree')}for(const r of D.refs)edge(map.get('f:'+r.from),map.get('f:'+r.to),'dep');$('files').textContent=D.files.length;$('rels').textContent=D.refs.length;$('load').style.display='none';layout()}
function $(id){return document.getElementById(id)}function layout(){const cx=W/2,cy=H/2,folders=nodes.filter(n=>n.folder);folders.forEach((n,i)=>{const a=-Math.PI/2+i/Math.max(1,folders.length)*Math.PI*2,r=Math.min(W,H)*.30;n.x=cx+Math.cos(a)*r;n.y=cy+Math.sin(a)*r});folders.forEach(f=>{const kids=nodes.filter(n=>!n.folder&&n.path.startsWith(f.path+'/'));if(!kids.length)return;const a=Math.atan2(f.y-cy,f.x-cx),r=Math.min(W,H)*.11;const span=Math.min(1.5,Math.max(.35,kids.length*.025));kids.forEach((n,i)=>{const aa=a-span/2+(i/Math.max(1,kids.length-1))*span;n.x=f.x+Math.cos(aa)*r;n.y=f.y+Math.sin(aa)*r})});const loose=nodes.filter(n=>!n.folder&&!n.path.includes('/'));loose.forEach((n,i)=>{const a=i/Math.max(1,loose.length)*Math.PI*2,r=Math.min(W,H)*.17;n.x=cx+Math.cos(a)*r;n.y=cy+Math.sin(a)*r})}
function P(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}function hit(mx,my){let z=null,bd=18;for(const n of nodes){const p=P(n),d=Math.hypot(mx-p.x,my-p.y);if(d<bd){bd=d;z=n}}return z}
function curve(a,b){const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1;const bend=Math.min(45,d*.18),nx=-dy/d,ny=dx/d;return{x:(a.x+b.x)/2+nx*bend,y:(a.y+b.y)/2+ny*bend}}
function draw(t){x.clearRect(0,0,W,H);for(const e of edges){const a=P(e.a),b=P(e.b),m=curve(a,b),on=selected&&(e.a===selected||e.b===selected)||hover&&(e.a===hover||e.b===hover);x.beginPath();x.moveTo(a.x,a.y);x.quadraticCurveTo(m.x,m.y,b.x,b.y);x.strokeStyle=on?'rgba(85,223,203,.85)':e.type==='dep'?'rgba(85,223,203,.20)':'rgba(130,120,170,.09)';x.lineWidth=on?1.7:e.type==='dep'?1:.6;x.stroke();if(e.type==='dep'&&!paused){const q=(t/2200+e.p)%1,xx=(1-q)*(1-q)*a.x+2*(1-q)*q*m.x+q*q*b.x,yy=(1-q)*(1-q)*a.y+2*(1-q)*q*m.y+q*q*b.y;x.beginPath();x.arc(xx,yy,2.2,0,Math.PI*2);x.fillStyle='#59e4b5';x.shadowBlur=12;x.shadowColor='#59e4b5';x.fill();x.shadowBlur=0}}
for(const n of nodes){const p=P(n),on=n===selected||n===hover||selected&&(adj.get(selected.id)||[]).includes(n),r=(n.folder?7:3.5)+(on?2:0);x.beginPath();x.arc(p.x,p.y,r,0,Math.PI*2);x.fillStyle=n.folder?'#9a7dff':on?'#72eee0':'#263640';x.shadowBlur=on?16:4;x.shadowColor=n.folder?'#9a7dff':'#59e4b5';x.fill();x.shadowBlur=0;if(on||zoom>.72){x.fillStyle=on?'#eaffff':'#718891';x.font=(on?'700 ':'500 ')+(n.folder?9:8)+'px ui-monospace';x.fillText(n.name,p.x+r+5,p.y+3)}}requestAnimationFrame(draw)}
function inspect(n){selected=n;if(!n){$('inspect').classList.remove('show');return}$('inspect').classList.add('show');$('name').textContent=n.folder?'📁 '+n.name:n.name;$('path').textContent=n.path;const a=adj.get(n.id)||[];$('links').innerHTML='<b>'+a.length+' relationships</b><br>'+a.slice(0,60).map(v=>'→ '+v.path).join('<br>')+(a.length>60?'<br>…':'')}
c.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;c.classList.add('drag')});addEventListener('pointerup',e=>{const was=drag;drag=false;c.classList.remove('drag');if(was&&Math.hypot(e.clientX-lx,e.clientY-ly)>4)return;inspect(hit(e.clientX,e.clientY))});addEventListener('pointermove',e=>{if(drag){panX+=e.clientX-lx;panY+=e.clientY-ly;lx=e.clientX;ly=e.clientY}else hover=hit(e.clientX,e.clientY)});c.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.2,Math.min(3,zoom*(e.deltaY<0?1.1:.9)));panX=e.clientX-(e.clientX-panX)*(zoom/old);panY=e.clientY-(e.clientY-panY)*(zoom/old)},{passive:false});
$('close').onclick=()=>inspect(null);$('center').onclick=()=>{zoom=.8;panX=0;panY=0;layout()};$('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'PLAY':'PAUSE';$('state').textContent=paused?'PAUSED':'LIVE'};$('refresh').onclick=()=>location.reload();$('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();const n=q?nodes.find(v=>v.path.toLowerCase().includes(q)):null;if(n){inspect(n);const p=P(n);panX+=W/2-p.x;panY+=H/2-p.y}else if(!q)inspect(null)};
async function heartbeat(){try{const r=await fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'}),d=await r.json();$('hb').textContent=d.time;$('state').textContent=paused?'PAUSED':'LIVE'}catch(e){$('hb').textContent='OFFLINE';$('state').textContent='OFFLINE'}}resize();build();requestAnimationFrame(draw);heartbeat();setInterval(heartbeat,2000);
